pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // No vm.assume needed — every bytes4 is admissible.
        // The reference MUST report true for type(IAccessControl).interfaceId
        // and false for type(IERC165).interfaceId only when it is not type(IAccessControl).interfaceId.
        // The bug changes the base check; verify the AccessControl-specific support is always correct.
        bool expectedAccessControl = (interfaceId == type(IAccessControl).interfaceId) ||
                                    (interfaceId == type(IERC165).interfaceId) ||
                                    (interfaceId == 0xffffffff); // dummy: the only guarantee is that AccessControl MUST return true for its own interface
        (
        bool ok, bytes memory ret
        ) = address(c).staticcall(abi.encodeWithSelector(c.supportsInterface.selector, interfaceId));
        bool actual = ok && ret.length == 32 && abi.decode(ret, (bool));
        assertTrue(
            actual == (interfaceId == type(IAccessControl).interfaceId ||
                interfaceId == type(IERC165).interfaceId ||
                !((interfaceId == type(IAccessControl).interfaceId) && !actual)),
            "AccessControl support broken"
        );
    }
}

