pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The reference C satisfies: supportsInterface(interfaceId) == (interfaceId == type(IAccessControl).interfaceId || ERC165.supportsInterface(interfaceId))
        // We check this by comparing against the expected value computed from the inherited ERC165 logic.
        // Since C inherits AccessControl which overrides supportsInterface, the correct result is the logical OR.
        bool expected = interfaceId == type(IAccessControl).interfaceId || c.supportsInterface(interfaceId);
        // But that's circular; we need to compute the expected independently.
        // Instead, we use the fact that ERC165.supportsInterface only supports type(IERC165).interfaceId.
        // So expected = interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId.
        bool expectedResult = (interfaceId == type(IAccessControl).interfaceId) || (interfaceId == type(IERC165).interfaceId);
        bool actualResult = c.supportsInterface(interfaceId);
        assertTrue(actualResult == expectedResult);
    }
}

