    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Only call internal grant via public admin flow: caller must be role admin
        // DEFAULT_ADMIN_ROLE is admin of itself by default, so we use it to grant
        vm.assume(role != 0x00); // avoid DEFAULT_ADMIN_ROLE to keep test simple
        vm.prank(address(this));
        // Grant DEFAULT_ADMIN_ROLE to us so we can later grant other roles
        c.grantRole(0x00, address(this));
        vm.prank(address(this));
        // Grant the fuzzed role to the fuzzed account
        c.grantRole(role, account);
        // After granting, the correct contract must report true, the mutant false
        assertTrue(c.hasRole(role, account));
    }
}

