        // Record hasRole before revoking a role the account likely doesn't have
        bool beforeRevoke = c.hasRole(role, account);
        // Grant admin to self to be able to call revokeRole
        vm.prank(address(this));
        c.grantRole(c.DEFAULT_ADMIN_ROLE(), address(this));
        vm.prank(address(this));
        // Call revokeRole on the same role and account (idempotent if not a member)
        c.revokeRole(role, account);
        bool afterRevoke = c.hasRole(role, account);
        // In P, revoking a role that an account does not have is a no-op on hasRole;
        // In M, hasRole always returns false, so afterRevoke also equals false,
        // but beforeRevoke could have been true. The invariant is that hasRole after
        // revoking an unheld role equals the value before revoking.
        assertTrue(beforeRevoke == afterRevoke);
    }
}

