pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        // The reference returns the stored admin role; the mutant always returns DEFAULT_ADMIN_ROLE.
        // For any role whose admin is not DEFAULT_ADMIN_ROLE, they differ.
        // We use a non-existent role to ensure it's never been set, so reference returns its default (bytes32(0)).
        // Since the mutant returns DEFAULT_ADMIN_ROLE (0x00), on a role that has never been set, both return 0x00 and the assertion holds.
        // To expose the difference, we must compare a role whose admin is NOT DEFAULT_ADMIN_ROLE.
        // In C's constructor, TIMELOCK_ADMIN_ROLE gets admin = TIMELOCK_ADMIN_ROLE (≠ 0).
        bytes32 timelockAdmin = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 refAdmin = c.getRoleAdmin(timelockAdmin);
        // Reference returns TIMELOCK_ADMIN_ROLE itself; mutant returns 0.
        // The property: getRoleAdmin(timelockAdmin) must NOT be DEFAULT_ADMIN_ROLE.
        assertTrue(refAdmin != bytes32(0x00));
    }
}
